import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/changespillover/changespillover_2021_2022_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Load data
df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Build adjacency dictionary
adj_dict = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in adj_dict:
        adj_dict[borough] = set()
    adj_dict[borough].add(neighbor)
    if neighbor not in adj_dict:
        adj_dict[neighbor] = set()
    adj_dict[neighbor].add(borough)

# Get list of boroughs
boroughs = df['borough'].tolist()
n = len(boroughs)
borough_to_index = {borough: idx for idx, borough in enumerate(boroughs)}

# Create spatial weights matrix
w = np.zeros((n, n))
for i in range(n):
    borough_i = boroughs[i]
    if borough_i in adj_dict:
        for j in range(n):
            borough_j = boroughs[j]
            if borough_j in adj_dict[borough_i]:
                w[i][j] = 1

# Compute observed Moran's I
x = df['delta_value'].values
x_bar = np.mean(x)

numerator_observed = 0
for i in range(n):
    for j in range(n):
        if w[i][j] > 0:
            numerator_observed += w[i][j] * (x[i] - x_bar) * (x[j] - x_bar)

denominator = np.sum((x - x_bar)**2)
I_observed = numerator_observed / denominator

# Permutation test
np.random.seed(42)  # for reproducibility
n_permutations = 500
count = 0

for _ in range(n_permutations):
    x_permuted = np.random.permutation(x)
    numerator_perm = 0
    for i in range(n):
        for j in range(n):
            if w[i][j] > 0:
                numerator_perm += w[i][j] * (x_permuted[i] - x_bar) * (x_permuted[j] - x_bar)
    I_permuted = numerator_perm / denominator
    if I_permuted >= I_observed:
        count += 1

p_value = (count + 1) / (n_permutations + 1)

# Determine final answer
if p_value < 0.05:
    print(f"FINAL ANSWER: CLUSTERED (test statistic = {I_observed}, p = {p_value})")
else:
    print(f"FINAL ANSWER: NOT CLUSTERED (test statistic = {I_observed}, p = {p_value})")
